begin;
create unique index if not exists competition_unique_active_station on public.competition_assignments(event_id,coalesce(match_id,'00000000-0000-0000-0000-000000000000'::uuid),role) where status not in ('absent');
create table if not exists public.team_actions(id uuid primary key default gen_random_uuid(),title text not null,details text,action_type text not null default 'assignment' check(action_type in ('assignment','milestone','announcement','training','meeting','other')),target_type text not null check(target_type in ('all','subteam','member')),target_value text,due_at timestamptz,priority text not null default 'normal' check(priority in ('low','normal','high','urgent')),source_table text,source_id uuid,created_by uuid references public.team_members(id) on delete set null default auth.uid(),cancelled boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.team_action_states(action_id uuid not null references public.team_actions(id) on delete cascade,member_id uuid not null references public.team_members(id) on delete cascade,status text not null default 'new' check(status in ('new','acknowledged','snoozed','completed')),snoozed_until timestamptz,acknowledged_at timestamptz,completed_at timestamptz,updated_at timestamptz not null default now(),primary key(action_id,member_id));
create table if not exists public.contribution_events(id uuid primary key default gen_random_uuid(),member_id uuid not null references public.team_members(id) on delete cascade,event_type text not null check(event_type in ('task_completed','attendance','skill_validated','test_run','issue_resolved','knowledge_shared','manual')),points numeric(8,2) not null default 0,reference_id uuid,description text,occurred_at timestamptz not null default now(),created_by uuid references public.team_members(id) on delete set null default auth.uid());
alter table public.team_actions enable row level security;alter table public.team_action_states enable row level security;alter table public.contribution_events enable row level security;
drop policy if exists "members view targeted actions" on public.team_actions;create policy "members view targeted actions" on public.team_actions for select to authenticated using(not cancelled and (target_type='all' or target_type='member' and target_value=auth.uid()::text or target_type='subteam' and lower(target_value)=lower(coalesce((select subteam from public.team_members where id=auth.uid()),''))));
drop policy if exists "members create actions" on public.team_actions;create policy "members create actions" on public.team_actions for insert to authenticated with check(public.current_team_role() is not null);drop policy if exists "admins manage actions" on public.team_actions;create policy "admins manage actions" on public.team_actions for update to authenticated using(public.is_admin()) with check(public.is_admin());
drop policy if exists "members manage own action state" on public.team_action_states;create policy "members manage own action state" on public.team_action_states for all to authenticated using(member_id=auth.uid()) with check(member_id=auth.uid());
drop policy if exists "members view own contribution" on public.contribution_events;create policy "members view own contribution" on public.contribution_events for select to authenticated using(member_id=auth.uid() or public.is_admin());drop policy if exists "team records contribution" on public.contribution_events;create policy "team records contribution" on public.contribution_events for insert to authenticated with check(public.current_team_role() is not null);
create index if not exists team_actions_target_idx on public.team_actions(target_type,target_value,due_at) where not cancelled;create index if not exists contribution_member_idx on public.contribution_events(member_id,occurred_at desc);
create or replace function public.publish_milestone_action() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.team_actions(title,details,action_type,target_type,target_value,due_at,priority,source_table,source_id,created_by) values(new.title,new.details,'milestone',case when new.owner_id is not null then 'member' when new.workstream='team' then 'all' else 'subteam' end,case when new.owner_id is not null then new.owner_id::text when new.workstream='team' then null else new.workstream end,case when new.due_at is null then null else new.due_at::timestamptz+interval '17 hours' end,case when new.status in ('blocked','at_risk') then 'high' else 'normal' end,'season_milestones',new.id,new.created_by);return new;end$$;
drop trigger if exists season_milestone_to_action on public.season_milestones;create trigger season_milestone_to_action after insert on public.season_milestones for each row execute function public.publish_milestone_action();
create or replace function public.publish_urgent_announcement_action() returns trigger language plpgsql security definer set search_path=public as $$begin if new.priority in ('high','urgent') then insert into public.team_actions(title,details,action_type,target_type,target_value,priority,source_table,source_id,created_by) values(new.title,new.body,'announcement',case when coalesce(new.audience,'all')='subteam' then 'subteam' else 'all' end,case when coalesce(new.audience,'all')='subteam' then new.audience_subteam else null end,new.priority,'announcements',new.id,new.created_by);end if;return new;end$$;
drop trigger if exists urgent_announcement_to_action on public.announcements;create trigger urgent_announcement_to_action after insert on public.announcements for each row execute function public.publish_urgent_announcement_action();
insert into public.team_actions(title,details,action_type,target_type,target_value,due_at,priority,source_table,source_id,created_by) select m.title,m.details,'milestone',case when m.owner_id is not null then 'member' when m.workstream='team' then 'all' else 'subteam' end,case when m.owner_id is not null then m.owner_id::text when m.workstream='team' then null else m.workstream end,case when m.due_at is null then null else m.due_at::timestamptz+interval '17 hours' end,case when m.status in ('blocked','at_risk') then 'high' else 'normal' end,'season_milestones',m.id,m.created_by from public.season_milestones m where m.status<>'completed' and not exists(select 1 from public.team_actions a where a.source_table='season_milestones' and a.source_id=m.id);
commit;
